    "answer": "فالزكاة تحقق ذلك بإسهام الفرد بجزء دوري من ماله للمساهمة في إعالة فئة غير قادرة على الكسب، والوقف يسهم في تحقيق ذلك من خلال إتاحة الفرصة للأفراد في تحقيق مصالح عامة معتبرة. كذلك فإن وظيفة المحتسب في مراقبة الأسواق والفصل في المنازعات وغيرها من مهام المحتسب تسهم في تحقيق هذا التوازن واستمراره في إطار من الأهداف المشتركة للفرد والمجتمع.",
