    "answer": "الأولى: أن الاقتصاد الإسلامي يعتقد أن المالك الحقيقي هو الله سبحانه وتعالى، وأن الملكية ملكية استخلاف لتعمير هذا الكون، وعلى المستخلف أن يتصرف في ضوء ما أباح المالك الحقيقي\n\nالثانية: أن الاقتصاد الإسلامي يأخذ بازدواجية الملكية الفردية والعامة بما فيها ملكية الدولة، وأن كليهما أصل وليس استثناء يفرضه الواقع.",
