    "answer": "كما يقر الملكية العامة كأصل وذلك في الموارد التي تقتضي طبيعتها عدم التملك كالأنهار والمعادن\n\nوتشمل الملكية العامة الطرق العامة والجسور والسدود التي ينتفع بها الناس\n\nويدخل ضمن هذا النوع من التملك الأوقاف الخيرية، وهي الأموال التي سمح الإسلام بخروجها من ملكية أصحابها لتكون وقفا على المصالح العامة.\n\nكما يدخل ضمن هذا النوع أراضي الحمى التي انتقلت بحكم الإمام من الإباحة الأصلية إلى الملكية العامة",
