    "answer": "علم دراسة وتحليل سلوك الفرد والمجتمع تجاه الموارد الإنتاجية من أجل تحقيق الرفاهة في إطار التعاليم الشرعية.\n\nمجموعة القواعد والأسس المنبثقة من الشريعة الإسلامية التي يسير عليها المجتمع لتنظيم شؤونه الاقتصادية.\n\nأي أن علم الاقتصاد الإسلامي يرتبط بشكل وثيق بالنظام الاقتصادي الإسلامي.",
