    "sourceKind": "book",
    "explanation": "",
    "answer": "إن مفهوم العدالة في النظام الاقتصادي الإسلامي لا يعني المساواة بين الأفراد في الدخل والثروة، لأن ذلك ينافي الفطرة الإنسانية التي خلق الله الناس عليها من تفاوت فيما هو أهم من المال وهو العقل والقدرات، ولعدم القدرة على تحقيق ذلك على أرض الواقع. بل تعني العدالة في المفهوم الاقتصادي الإسلامي إتاحة الفرص المتساوية لجميع أفراد المجتمع لاستخدام قدراتهم من خلال السوق، واستغلالها بما يحقق النفع لهم، مع الاهتمام بالفئات غير القادرة على الكسب بما يكفل لهم مستوى معيشياً مناسباً.",
