    "answer": "أ- توزيع الثروة (التوزيع الشخصي): يسعى الاقتصاد الإسلامي فيما يتعلق بتوزيع مصادر الثروة إلى الاعتداد بأهمية توفير العدالة من خلال تخفيض مستوى التفاوت بين الأفراد وضبطه في حدود معقولة. لذلك أقر الإسلام كلاً من الملكية الفردية والعامة دون تضاد، وتدخل الملكية الفردية على مصادر الثروة من خلال الجهد البشري والمال الخاص، كما تدخل الملكية العامة على مصادر أخرى محددة من أجل تحقيق التوازن الاقتصادي والاجتماعي.\n\nب- توزيع الدخل على أصحاب عناصر الإنتاج (التوزيع الوظيفي): بما يضمن حصول كل مشترك في العملية الإنتاجية على عائد نظير اشتراك خدمات عوامل الإنتاج من خلال السوق، مما يسهم في تحقيق العدالة من جهة، ويحفز على تحقيق الكفاءة الاقتصادية للقطاع الإنتاجي من جهة أخرى. كما أن تحريم الاقتصاد الإسلامي للفائدة الربوية يفعّل تحقيق تلك الأهداف.\n\nج- إعادة توزيع الدخل والثروة: يعمل الاقتصاد الإسلامي على تسهيل تحقيق العدالة من خلال المرحلتين السابقتين ثم بعد ذلك من خلال أدوات رئيسة يتميز بها وذات فاعلية في تحقيق العدالة، ومن أبرزها الزكاة والكفارات ونظام الإرث.",
