    "answer": "الثاني: خلقه تعالى بقدر في هذا الكون. وهذا النوع يتطلب الحصول عليه ثمناً وجهداً لأن القدر المتوافر منه محدود نسبياً. ولو كانت هذه الموارد متوافرة كالموارد الحرة لانتفت المشكلة الاقتصادية، ولاتصاف هذه الموارد بالندرة النسبية اصطلح على تسميتها بالموارد الاقتصادية.",
