    "explanation": "",
    "answer": "أ- معنى ذلك أن الموارد الاقتصادية كثيرة جداً، وللإنسان أن يستخدمها كيف شاء فلا ضرر من ذلك.\n\nب- إن نفي المشكلة الاقتصادية ينافي الفطرة الإنسانية من حب الإنسان للمال\n\nومحبة الإنسان للشيء وحرصه على اقتنائه لا يكونان إلا للشيء النادر الذي له قيمة.\n\nج- نفي المشكلة الاقتصادية يتعارض مع المقصود من الأوامر الشرعية في السلوك الاقتصادي\n\nفلماذا ينهى الإسلام عن الإسراف والتبذير ما دامت الموارد متوافرة بكثرة؟\n\nد- نفي المشكلة الاقتصادية يؤدي إلى القول بأن الاقتصاد الإسلامي اقتصاد ساكن لأن المشكلة الاقتصادية المحرك الرئيس للنشاط الاقتصادي.\n\nهـ- ينادي البعض ممن ينفي الندرة النسبية بضرورة ترشيد الحاجات وتحديدها، وهذا تناقض، فلماذا نرشد الحاجات ما دام الإنسان لا يواجه مشكلة اقتصادية؟",
