    "answer": "١- ماذا ننتج؟ أي تحديد احتياجات المجتمع من السلع أو الخدمات نوعاً وكماً، وترتيبها وفق أهميتها.\n٢- كيف ننتج؟ اختيار أساليب الإنتاج، والجهات التي تتولى القيام بمسؤوليات الإنتاج في المجتمع.\n٣- لمن ننتج؟ اختيار طريقة توزيع السلع الاستهلاكية على الأفراد، وتوزيع سلع الاستثمار على قطاع الأعمال من أجل إعادة استثمار ذلك الجزء لزيادة طاقة المجتمع الإنتاجية وتخصيص جزء من الناتج إلى الحكومة للقيام بوظائفها في النشاط الاقتصادي.",
