    "answer": "تشمل الملكية الفردية كل أنواع الثروة المختلفة من أراض ومبان وآلات وسلع وغيرها، فللأفراد تملك هذه الأشياء والتصرف فيها.\n\nولا تتنافى هذه الملكية مع الملكية العامة لبعض المشروعات كالكهرباء والسكك الحديدية أو الطرق والجسور. كما لا تتعارض الملكية الفردية وما يرتبط بها من حرية التصرف مع قيام القانون بتنظيم استخدام هذا الحق، فقد ينص القانون على عدم الاستثمار في نشاط معين كإنتاج الأسلحة أو غيرها.",
