    "answer": "يعد الربح المحرك الرئيس للنشاط الاقتصادي في ظل هذا النظام، حيث يحدد الربح نوع النشاط الاقتصادي الذي يفضله الأفراد الذين يتخذون القرارات الإنتاجية بغية الحصول على أكبر عائد ممكن. وبسبب عائد الربح يتميز الاقتصاد الرأسمالي بوجود عدد كبير من أصحاب المشروعات الإنتاجية الذين يتخذون قرارات إنتاجية باستمرار. ولذلك فإن غياب هذا الحافز يقوض أركان النظام الرأسمالي.",
