    "answer": "يقوم السوق بدور رئيس في النظام الرأسمالي، فعن طريق السوق يتم تخصيص الموارد الاقتصادية للمجتمع، فالمنظم يؤلف بين عوامل الإنتاج في وحدة إنتاجية بمراعاة أثمان هذه العناصر الإنتاجية من أجل إنتاج السلع والخدمات التي تحقق له أقصى عائد ممكن. والمستهلك استرشاداً بالأثمان السائدة في السوق وبمراعاة قدراته الشرائية يقرر توزيع دخله المتاح بين السلع والخدمات بما يحقق له أكبر نفع ممكن.",
