    "answer": "تعمل المنافسة بين الأفراد على منع استغلال الأفراد والجماعات بعضهم لبعض، ما يعطي للمنافسة دوراً رقابياً وتنظيمياً، فإذا أراد المنتج استغلال المستهلك برفع السعر مثلاً فإنه يسمح لغيره من المنتجين بالدخول إلى إنتاج نفس السلعة، ما ينتج عنه زيادة كمية الإنتاج من هذه السلعة عن المطلوب، وبالتالي انخفاض السعر.",
