    "answer": "ويلاحظ أن جهاز السوق عندما يقوم بحل المشكلة الاقتصادية لا يقوم بحل كل عنصر من عناصر المشكلة الاقتصادية (ماذا ننتج؟ كيف ننتج؟ لمن ننتج؟) بصورة منفصلة، بل إن آلية السوق تؤثر على جميع تلك العناصر في نفس الوقت، فمثلاً يؤدي تحول المستهلكين من طلب بعض السلع في السوق إلى تقليل أهميتها وعائدها، ما يحول المنتجين من إنتاج تلك السلع إلى سلع أخرى يرغبها المستهلك ويطلبها، وهذا من شأنه توجيه موارد المجتمع نحو إشباع الحاجات التي يفضلها الأفراد، كما أنه يعمل على رفع كفاءة الإنتاج من خلال فتح مجال المنافسة للراغبين في المشاركة في العملية الإنتاجية والقادرين عليها.",
