    "answer_phrase": "ومع أن قيام السوق بهذا الدور يتوقف على مدى تمتع موارد المجتمع بقدر كبير من الحرية في الانتقال بين الأنشطة الإنتاجية، إلا أن هناك عوائق ذات طابع فني تجعل انتقالها من نشاط إنتاجي إلى آخر أمراً صعباً، فالعامل في مصنع الحديد والصلب يصعب عليه الانتقال إلى صناعة الأجهزة الكهربائية، وقد تعود إلى عوائق جغرافية أو قانونية تمنع انتقال العنصر الإنتاجي من مكان إلى آخر.",
