    "sourceKind": "book",
    "explanation": "",
    "answer": "١- يؤدي النظام الرأسمالي إلى مزيد من تفاوت الدخل والثروة وتركزها في يد فئة قليلة، تستحوذ على معظم ثروة المجتمع وموارده على حساب الفئة الأوسع التي يتناقص نصيبها من الموارد والثروات باستمرار، بما له من أخطار اجتماعية وأمنية.\n\nولذا فقد حاول النظام الرأسمالي التخفيف من ذلك بسن القوانين التي تفرض حداً أدنى للأجور وفرض ضرائب تصاعدية وتقديم معونات اجتماعية من خلال الدور الذي يقوم به القطاع التطوعي كالجمعيات الخيرية والمنظمات غير الحكومية التي لا تهدف إلى الربح في تخفيف آثار المشكلة الاقتصادية على الفئات غير القادرة.",
