    "explanation": "",
    "answer": "٢- أصبحت الشركات الاحتكارية الكبرى من سمات النظام الرأسمالي حتى مع وجود عنصر المنافسة، لأن أدوات هذا النظام كالحرية الاقتصادية المطلقة وأسلوب التمويل المعتمد على الفائدة يدعم دور هذه الشركات، خاصة أن تلك الشركات تملك جهازاً إدارياً وتسويقياً ضخماً، تستطيع من خلاله التأثير المباشر والسريع على المشروعات الصغيرة ويقلل قدرتها على الاستمرار. بالإضافة إلى قدرة تلك الشركات الاحتكارية على ضمان مصالحها من خلال دعم حملات بعض الرموز السياسية لضمان حماية مصالحها. وإن كان النظام الرأسمالي قد حاول مناهضة الاحتكار والتخفيف من أضراره بسن الأنظمة وإنشاء الأجهزة المناهضة للاحتكار.",
