    "answer": "٤- للمنافسة في النظام الرأسمالي مزايا وآثار إيجابية. إلا أنها في مقابل ذلك لها آثار سلبية عديدة؛ أهمها النفقات الباهظة للدعاية والإعلان من أجل الترويج لهذه السلع، خاصة الجديدة منها، وهذه النفقات وجه من أوجه الإسراف والتبذير وإهدار الموارد في ظل النظام الرأسمالي، ومع أن المنتج يتحمل هذه النفقات إلا أنه في الحقيقة يقوم بنقل عبء هذه التكاليف بإدخالها ضمن تكاليف الإنتاج إلى المستهلك الذي يتحمل الأضرار الناتجة عن التوسع في أساليب الدعاية والإعلان، خاصة مع انحراف الدور الطبيعي للإعلان من التعريف بالسلعة ومواصفاتها إلى محاولة فرضها على خريطة المستهلك بتكرار أساليب الدعاية وتعدد أساليبها.",
