    "answer": "ولا يرى النظام الاقتصادي الاشتراكي أن المشكلة الاقتصادية مشكلة ندرة الموارد مقابل تعدد الحاجات، بل يراها مشكلة أساسها التناقض بين أشكال الإنتاج وعلاقات التوزيع، وأن حل هذه المشكلة يستلزم التوفيق بينهما ليسود الاستقرار الحياة الاقتصادية، وذلك بإلغاء أدوات النظام الرأسمالي كالملكية الفردية والحرية الاقتصادية والسوق واستبدال الملكية العامة (ملكية الدولة) لوسائل الإنتاج والدور الرئيس لجهاز التخطيط المركزي بها، ولذلك سنعرض فيما يأتي أبرز الأدوات التي استخدمها النظام الاشتراكي في مواجهة المشكلة الاقتصادية.",
