    "answerMode": "exact-quote",
    "answerItems": [
      "إهمال هذا النظام لمبادئ الملكية الفردية والحرية الاقتصادية والدور المهم لآلية السوق. وفضلاً عن مصادمته للفطرة الإنسانية فإنه يفتقد الواقعية، إذ لا يمكن تصور قيام نشاط اقتصادي متعدد دون وجود مثل هذه الأدوات الاقتصادية الفعالة التي لا يمكن أن يستغنى عنها بالكامل أي نظام اقتصادي يسعى إلى مواجهة المشكلة الاقتصادية.",
      "اعتمد النظام الاشتراكي في مواجهة المشكلة الاقتصادية على جهاز التخطيط المركزي، وهذا يعني أن هذا الجهاز مسؤول عن اتخاذ آلاف القرارات الاقتصادية اليومية، وهو ما أدى إلى وجود جهاز إداري ضخم اتصف بالبيروقراطية والتعقيد الإداري الشديد (عدم المرونة) الذي يتنافى مع حركية النشاط الاقتصادي وسرعة اتخاذ القرارات فيه.",
      "أغفل النظام الاقتصادي الاشتراكي الجوانب الأخلاقية والاجتماعية والدينية للفرد، بما لها من تأثير مهم على سلوك الفرد، فضلاً عن أن إهمالها يؤثر بشكل سلبي على إنتاجية الفرد ومبادراته وابتكاراته، ما يضعف الكفاءة الإنتاجية للعاملين في ظل هذا النظام، نظراً لعدم وجود الحوافز لهؤلاء العاملين، الذين هم ركن أساسي في مواجهة المشكلة الاقتصادية. فضلاً عما عانى منه هذا النظام من إهدار للموارد وتفاوت كبير في توزيع الدخل والثروة بشكل يفوق ما هو موجود في النظام الرأسمالي، وهو ما أدى إلى سرعة انهيار هذا النظام على مستوى التطبيق في العديد من دول العالم."
    ],
    "answer_phrase": "١- إهمال هذا النظام لمبادئ الملكية الفردية والحرية الاقتصادية والدور المهم لآلية السوق. وفضلاً عن مصادمته للفطرة الإنسانية فإنه يفتقد الواقعية، إذ لا يمكن تصور قيام نشاط اقتصادي متعدد دون وجود مثل هذه الأدوات الاقتصادية الفعالة التي لا يمكن أن يستغنى عنها بالكامل أي نظام اقتصادي يسعى إلى مواجهة المشكلة الاقتصادية.\n\n٢- اعتمد النظام الاشتراكي في مواجهة المشكلة الاقتصادية على جهاز التخطيط المركزي، وهذا يعني أن هذا الجهاز مسؤول عن اتخاذ آلاف القرارات الاقتصادية اليومية، وهو ما أدى إلى وجود جهاز إداري ضخم اتصف بالبيروقراطية والتعقيد الإداري الشديد (عدم المرونة) الذي يتنافى مع حركية النشاط الاقتصادي وسرعة اتخاذ القرارات فيه.\n\n٣- أغفل النظام الاقتصادي الاشتراكي الجوانب الأخلاقية والاجتماعية والدينية للفرد، بما لها من تأثير مهم على سلوك الفرد، فضلاً عن أن إهمالها يؤثر بشكل سلبي على إنتاجية الفرد ومبادراته وابتكاراته، ما يضعف الكفاءة الإنتاجية للعاملين في ظل هذا النظام، نظراً لعدم وجود الحوافز لهؤلاء العاملين، الذين هم ركن أساسي في مواجهة المشكلة الاقتصادية. فضلاً عما عانى منه هذا النظام من إهدار للموارد وتفاوت كبير في توزيع الدخل والثروة بشكل يفوق ما هو موجود في النظام الرأسمالي، وهو ما أدى إلى سرعة انهيار هذا النظام على مستوى التطبيق في العديد من دول العالم.",
