    "explanation": "",
    "answer": "تشمل الملكية الفردية كل أنواع الثروة المختلفة من أراض ومبان وآلات وسلع وغيرها، فللأفراد تملك هذه الأشياء والتصرف فيها.\n\nولا تتنافى هذه الملكية مع الملكية العامة لبعض المشروعات كالكهرباء والسكك الحديدية أو الطرق والجسور. كما لا تتعارض الملكية الفردية وما يرتبط بها من حرية التصرف مع قيام القانون بتنظيم استخدام هذا الحق، فقد ينص القانون على عدم الاستثمار في نشاط معين كإنتاج الأسلحة أو غيرها.\n\nاستبدل النظام الاشتراكي بالملكية الخاصة الملكية العامة (الدولة) لجميع المشروعات الاقتصادية داخل المجتمع، سواء كانت مشروعات زراعية، أم صناعية، أم موارد طبيعية، مع إلغاء الملكية الخاصة إلا في حدود ضيقة، بشرط ألا يستخدم العمل الأجري في استغلال هذا النوع من الملكية المسموح به.",
