    "answer": "أما عن كيفية توزيع الناتج على أصحاب العناصر الإنتاجية المساهمة في العملية الإنتاجية، فيتم ذلك أيضاً وفق آلية السوق، حيث يحصل كل صاحب عنصر إنتاجي مشارك على دخل يتحدد بعاملين:\n١- مقدار ما يملكه من عناصر الإنتاج.\n٢- سعر العنصر السائد في السوق.\n\nحيث إن عناصر الإنتاج في النظام الاشتراكي كانت مملوكة للدولة باستثناء العمل، فإن عوائد عناصر الإنتاج تعود للدولة ولا يوزع على الأفراد إلا عائد العمل، حيث يتوقف نصيب الفرد على مستوى عمله وطبيعته.",
