    "answer": "وبذلك فإن المشكلة الاقتصادية تظهر من خلال تعدد وتنوع حاجات الإنسان في مقابل الندرة النسبية للموارد الصالحة لإشباع تلك الحاجات، وما يوضح ويؤكد المشكلة الاقتصادية صلاحية المورد الواحد لأكثر من استخدام.\n\nولا يرى النظام الاقتصادي الاشتراكي أن المشكلة الاقتصادية مشكلة ندرة الموارد مقابل تعدد الحاجات، بل يراها مشكلة أساسها التناقض بين أشكال الإنتاج وعلاقات التوزيع، وأن حل هذه المشكلة يستلزم التوفيق بينهما ليسود الاستقرار الحياة الاقتصادية، وذلك بإلغاء أدوات النظام الرأسمالي كالملكية الفردية والحرية الاقتصادية والسوق واستبدال الملكية العامة (ملكية الدولة) لوسائل الإنتاج والدور الرئيس لجهاز التخطيط المركزي بها، ولذلك سنعرض فيما يأتي أبرز الأدوات التي استخدمها النظام الاشتراكي في مواجهة المشكلة الاقتصادية.",
