    "sourceKind": "book",
    "explanation": "",
    "answer": "١- يعتبر الإسلام الإنتاج عملاً دنيوياً مهماً وواجباً يثاب عليه المسلم،\n\n٢- نهى الإسلام عن كنز المال وحبسه عن التداول حتى لا تعطل منافع الناس في إقامة المشروعات الإنتاجية التي تشبع الحاجات الأساسية،\n\n٣- أن تشريعات الإسلام المتعلقة بمنع تركز الثروة كنظام الإرث ونظام الزكاة وإن كانت تتعلق بصورة مباشرة بتوزيع الدخل والثروة إلا أن لها آثاراً غير مباشرة على تنمية الإنتاج.\n\n٤- شجع الإسلام الإنفاق الاستثماري الذي يؤدي إلى تنمية الإنتاج وفضله على الإنفاق الاستهلاكي،\n\n٥- يتبنى الاقتصاد الإسلامي تقديم الحوافز للمنتج لتعظيم الأرباح من خلال آلية السوق التي تعمل على زيادة معدل الكفاءة الاقتصادية للمجتمع في تخصيص الموارد بإنتاج السلع والخدمات التي يرغبها الأفراد من جهة، وتحقيق أهداف المنتج بتعظيم أرباحه من جهة أخرى،\n\n٦- من وسائل الاقتصاد الإسلامي التي تؤدي إلى تنمية الإنتاج الزكاة،",
