    "explanation": "",
    "answer": "أولاً: تدل العديد من الآيات القرآنية الصريحة على وجود هذه المشكلة التي سيواجهها الفرد والمجتمع،\n\nثانياً: تنقسم الندرة إلى ثلاثة أقسام:\n(أ) ندرة مطلقة: تعني القلة، أي إن الموارد ليست كافية على مستوى الكون، وهذه لا يقرها الاقتصاد الإسلامي، كما أنها ليست المقصودة هنا.\n\n(ب) الندرة الإقليمية: بمعنى أن المورد موجود في إقليم ونادر في آخر ندرة ملموسة ومحسوسة، فالنفط مورد متوافر في الخليج العربي بينما هو نادر في اليابان.\n\n(ج) الندرة النسبية: وهي المقصودة عند دراسة المشكلة الاقتصادية، لا تعني عدم كفاية الموارد وقلتها، بل معناها صلاحية المورد الاقتصادي لأكثر من استخدام، ما يفرض الاختيار، إذ لو كان لكل مورد استخدام وحيد لانتفت المشكلة الاقتصادية بحيث يوجه المورد للاستخدام الذي يصلح له. فهل الموارد الاقتصادية ذات استخدام وحيد؟\n\nثالثاً: إن المشكلة الاقتصادية في الاقتصاد الإسلامي بالإضافة إلى كونها ظاهرة مشاهدة، فقد أقرها الفقهاء،\n\nرابعاً: يعتبر وجود المشكلة الاقتصادية المحرك الرئيس للنشاط الاقتصادي، حيث يقوم كل نظام اقتصادي بالإجابة عن ماذا ننتج؟ وكيف ننتج؟ ولمن ننتج؟ من خلال الدراسات الاقتصادية ضمن إطار علم الاقتصاد، فإذا تم نفي المشكلة الاقتصادية فمن الصعب قبول فكرة نظام اقتصادي إسلامي أو علم الاقتصاد الإسلامي.\n\nخامساً: إن المشكلة الاقتصادية ظاهرة يواجهها الفرد والمنشأة والمجتمع، وهذه الظاهرة الاقتصادية ذات أسباب طبيعية تقوم على أساس الندرة النسبية، وقد تعود إلى أسباب اجتماعية، وهي تحفز الأفراد والمجتمعات أن يعملوا بجد في الوقت والمكان وحسب نوع الحاجة بما يتفق مع سنة خلق الله للإنسان وحثه على السعي في طلب الرزق.\n\nسادساً: ليست المشكلة الاقتصادية ذات مستوى ثابت، بل قد تزيد حدتها أو تخف لدى الأفراد والمجتمعات بحسب إيمانهم. فهي مجال للاختبار والابتلاء للمؤمنين عند اشتداد حدتها\n\nسابعاً: إن نفي المشكلة الاقتصادية في الاقتصاد الإسلامي فضلاً عن كونه مخالفاً للواقع فإنه يؤدي إلى نتائج سلبية غير صحيحة منها:",
    "verificationStatus": "verified",
