    "answer": "وبذلك فإن مفهوم الإنتاج يشمل إنتاج أنواع السلع (المادية) والخدمات (غير المادية) النافعة للإنسان، بل وللحيوانات والطيور، بالإضافة إلى أهمية الجوانب النفسية في الإنتاج في التأثير على الجوانب المادية للنشاط الإنتاجي، كما بين رسول الله ﷺ في قوله: \"ما من مسلم يزرع زرعاً أو يغرس غرساً فيأكل منه طير أو إنسان أو بهيمة إلا كان له به صدقة\". في حين ركز الاقتصاد الغربي بشكل كبير على الجانب المادي للنشاط الإنتاجي، في مقابل اهتمام أقل بالجوانب الأخرى لهذا النشاط عند تناوله لمفهوم الإنتاج.",
