    "answer": "1- اكتشاف الموارد وتجديدها وتعظيم الاستفادة منها.\n2- أن العمارة تستلزم بذل الجهد والعمل الجاد المتقن.\n3- أنها تشمل أنشطة متنوعة كالزراعة والصناعة والتعلم وغيرها، وهي بذلك تتضمن أنواعاً مختلفة من الأنشطة الإنسانية.\n4- نظراً لأن أداء الإنسان لواجباته الشرعية واستقرار حياته لا يتحقق إلا بالعمارة، فإن الأمر بالعمارة على سبيل الوجوب والإلزام.\n5- أن العمارة تعتمد على الإنسان وقدراته على تنظيم العمل والاستفادة من الموارد بشكل أمثل.",
