    "answer": "ومن أمثلة الضوابط الملزمة الدائمة ضابط الحلال والحرام، إذ لا يمكن تحت أي ظرف أو مسوغ أن يقال بإلغائه، بدعوى وجود طلب أو ارتفاع العائد في إنتاج أو تداول سلع أو خدمات محرمة، كالخمر أو المخدرات أو دور اللهو المحرم مثلاً، وكالتمويل الربوي لإقامة مشروعات إنتاجية مباحة.",
