    "sourceKind": "book",
    "explanation": "",
    "answer": "1- الاعتماد المفرط على الخارج في توفير السلع والخدمات بما له من أضرار سلبية على المجتمع وقدرة قطاعاته الإنتاجية على المنافسة.\n2- إن التركيز القطاعي يؤدي إلى نقص الخبرة والمعرفة الإنسانية واقتصارها على ذلك القطاع، ما يعني الحد من اكتساب وتنوع المهارات، وتخلف القطاعات الإنتاجية الأخرى.\n3- تتصف العديد من المجتمعات بوجود موارد طبيعية متنوعة، ولذلك فإن من الطبيعي في حالة تركيز النشاط في قطاع إنتاجي معين، أن يتم إهدار العديد من الموارد أو عدم القدرة على الاستفادة منها، ولا ريب أن ذلك يعد إهمالاً يتحمل نتائجه اقتصاد المجتمع.\n4- يؤدي التركيز القطاعي إلى شدة تعرض الاقتصاد إلى تقلبات ذلك القطاع، خاصة بسبب تقلب الطلب الخارجي، ما يعرض الاقتصاد والموازنة العامة وميزان المدفوعات لهزات عنيفة تؤثر على أداء الاقتصاد، ويتضح ذلك بصورة أكبر عندما تكون منتجات ذلك القطاع من المواد الأولية التي تحتكر الدول المستوردة القدرة الفنية على تصنيعها.",
