    "answer": "1- وجوب اهتمام الحكومة بتوفير العمل لكل قادر من خلال إيجاد فرص العمل الجديدة، وتطوير المهارات والقدرات الفنية للأفراد.\n2- يجعل الاقتصاد الإسلامي العمل واجباً على كل قادر، وفرضاً من الله على الإنسان لتحصيل المعاش، فلا مكان للمتواكل أو المتكاسل لأن ذلك يتنافى مع توجيهات الإسلام في الحياة.\n3- من ضوابط الاقتصاد الإسلامي تجاه العمل، أنه نظم العلاقة بين صاحب العمل والعامل، فحث على أن تكون العلاقة إنسانية قوامها الأخوة في الله،\n4- من الضوابط المهمة تناسب العمل مع الأجر بما يحقق العدالة، ويرتبط بهذا الضابط أن التفاوت في الأجر يكون بحسب طبيعة العمل ودرجة إتقانه، وهو ما ينسجم مع التفاوت الطبيعي في القدرات والمهارات بين الأفراد، ما يؤدي إلى تنمية الحافز لدى أفراد المجتمع في التنافس فيما بينهم لتطوير قدراتهم ومهاراتهم.",
