    "answer_phrase": "أ- حق الاستعمال لما لديه من أموال عينية، وإنفاق الأموال النقدية لما يحتاجه من سلع وخدمات.\nب- حق التصرف المشروع كالهبة والعطية وسائر أنواع التصرفات الأخرى.\nج- حق الاستثمار لماله بالطرق المشروعة.\nد- حق توريث ماله لورثته دون اعتداء عليه، ما يحفز الفرد على بذل الجهد بتنمية المال، لاطمئنانه أن نفعه سيعود إلى ورثته من بعده.\nهـ- حق الحماية لماله من اعتداء الغير عليه.",
