    "answer": "حرص الاقتصاد الإسلامي على المحافظة على رأس المال وعدم إهداره. ويستدل على ذلك بقول رسول الله ﷺ لمن هم بذبح شاة: «إياك والحلوب»، لأن ذلك إهدار لرأس مال منتج، كما يؤكد ذلك قوله ﷺ: «من باع داراً أو عقاراً ولم يجعل ثمنها في مثلها -رأس مال إنتاجي- لم يبارك الله له»، ولذلك يؤدي هذا الضابط إلى المحافظة على رأس المال في المجتمع وعدم إهداره. ويوضح عمر بن الخطاب رضي الله عنه ذلك عندما سأل أحد الناس: ما عطاؤك؟ فقال: ألفان، فقال له عمر رضي الله عنه: «اتخذ منه الحرث والثابتات».",
