    "answer": "1- لأن له الحق في تقليل المخاطرة التي يتحملها رأس ماله باشتراط ما يحقق له ذلك. كما في قصة العباس حيث اشترط على صاحبه ألا يشتري برأس ماله ذات كبد رطبة ولا ينزل به وادياً، فرفع شرطه إلى النبي ﷺ فأجازه.\n2- يتولى صاحب رأس المال اختيار المضارب، ما يعني قدرته على تقليل المخاطرة باختيار المضارب الكفء.\n3- أن المضارب يجازف ويخاطر بالمقابل المادي للجهد الذي يبذله، وهو ليس يسيراً، إذ المضارب لا يقدم على تحمل هذه المخاطرة إلا إذا توقع ربحاً أو عائداً أكبر من أجر مثله في السوق، أما لو كان ما يتوقعه ليس كذلك فليس من مصلحته القيام بهذا الدور، بل يفضل أن يحصل على أجر محدد ومضمون سلفاً دون تحمل أي مخاطرة.",
