    "answer": "وقد أضاف الحنفية والحنابلة استحقاق الربح بالضمان، ويستدلون على ذلك بأن الشريك الوجيه في شركة الوجوه يستحق الربح بالضمان (ضمان المال) كما يستحقه الشريك في التقبل بناء على الضمان (ضمان العمل)، ولهذا فإن العمل والمال يستحقان الربح على وجه الاستقلال، أما الضمان فلا يستحق الربح إلا على وجه التبعية، حتى عند الحنفية والحنابلة ضمان مال، وتارة ضمان عمل على رأي البعض.",
