    "sourceKind": "book",
    "explanation": "وهنا نجد الرسول ﷺ ساهم بإيجاد فرصة عمل مناسبة له، بل ووجهه لكيفية استخدام مهاراته.",
    "answer": "تصرف الرسول ﷺ مع الرجل الذي أتاه يسأل فقال له: «أما في بيتك شيء؟» فقال: بلى، حلس نلبس بعضه ونبسط بعضه، وقعب نشرب فيه الماء، فقال ﷺ: «ائتني بهما» فأتاه بهما فأخذهما ﷺ وقال: «من يشتري هذين؟» فقال رجل: أنا آخذهما بدرهم، وكررها ﷺ فقال الرجل: أنا آخذهما بدرهمين. فأعطاهما إياه. وأخذ الدرهمين وأعطاهما الأنصاري وقال: «اشتر بأحدهما طعاماً فانبذه إلى أهلك واشتر بالآخر قدوماً فأتني به»، فأتاه به فشد فيه رسول الله ﷺ عوداً بيده، ثم قال: «اذهب فاحتطب وبع ولا أرينك خمسة عشر يوماً»، فذهب الرجل يحتطب ويبيع، فجاء وقد أصاب عشرة دراهم فاشترى ببعضها ثوباً وببعضها طعاماً، فقال رسول الله ﷺ: «هذا خير لك من أن تجيء المسألة نكتة في وجهك يوم القيامة. إن المسألة لا تصلح إلا لثلاثة: لذي فقر مدقع، أو لذي غرم مفظع، أو لذي دم موجع».",
    "quotationLabel": "مقتطف كما ورد في الكتاب",
